  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Terameprocol, a lipophilic polyphenolic drug, showed absolute oral bioavailability of ~2% in patients, far below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Eliglustat PBPK simulation predicted absolute oral bioavailability of 0.086 (8.6%), below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Bambuterol oral bioavailability is about 10% in healthy adults, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Halofantrine, the closest structural analogue with a dibutylamino alcohol and chlorinated polycyclic core, has low and erratic oral bioavailability in humans and animals.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "A retrospective estimate put halofantrine fasted absolute bioavailability at ~30%, above the threshold, but this is based on separate oral/IV studies and conflicts with direct low-F observations.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C06"],
      "claim": "Terbutaline absolute oral bioavailability was 14.8% in healthy volunteers, below the 20% threshold.",
      "evidence_role": "supportive"
    },
